CREATE FUNCTION `fn_name_initials`(name_text VARCHAR(128)) RETURNS varchar(64) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci
    DETERMINISTIC
BEGIN
  DECLARE i INT DEFAULT 1;
  DECLARE n INT DEFAULT 0;
  DECLARE ch VARCHAR(8);
